-- CSC 307 Group 1 - Topic 01: Basic and Senior High School Performance Data Warehouse
-- Upper West Region, Ghana. SYNTHETIC DATA. Generated by generate_data.py v1.0.0
-- Target: PostgreSQL 13+ (also runs on DuckDB). Dimensions first, then facts.

DROP TABLE IF EXISTS fact_exam_result, fact_enrolment, fact_staffing, dim_date, dim_location, dim_school, dim_learner, dim_subject, dim_examination, dim_teacher, dim_academic_term;

-- dim_date: One row per calendar day, 2020-09-01 to 2025-12-31. SCD: Type 0 (static)
CREATE TABLE dim_date (
    date_key                           INTEGER        PRIMARY KEY,
    full_date                          DATE           NOT NULL,
    day_name                           VARCHAR(9)     NOT NULL,
    day_of_week                        SMALLINT       NOT NULL,
    day_of_month                       SMALLINT       NOT NULL,
    month_number                       SMALLINT       NOT NULL,
    month_name                         VARCHAR(9)     NOT NULL,
    quarter                            SMALLINT       NOT NULL,
    year                               SMALLINT       NOT NULL,
    is_weekend                         BOOLEAN        NOT NULL,
    is_public_holiday                  BOOLEAN        NOT NULL,
    holiday_name                       VARCHAR(40),
    season                             VARCHAR(5)     NOT NULL
);

-- dim_location: One row per town or community in the region's 11 districts (conformed dimension). SCD: Type 1
CREATE TABLE dim_location (
    location_key                       INTEGER        PRIMARY KEY,
    region                             VARCHAR(20)    NOT NULL,
    district_code                      VARCHAR(4)     NOT NULL,
    district                           VARCHAR(30)    NOT NULL,
    district_capital                   VARCHAR(20)    NOT NULL,
    town                               VARCHAR(30)    NOT NULL,
    urban_rural                        VARCHAR(5)     NOT NULL,
    electoral_area                     VARCHAR(40)    NOT NULL,
    latitude                           DECIMAL(8,5)   NOT NULL,
    longitude                          DECIMAL(8,5)   NOT NULL
);

-- dim_school: One row per school per version of its facilities; a new row is added when a tracked attribute changes. SCD: Type 2
CREATE TABLE dim_school (
    school_key                         INTEGER        PRIMARY KEY,
    emis_code                          VARCHAR(12)    NOT NULL,
    school_name                        VARCHAR(40)    NOT NULL,
    school_level                       VARCHAR(7)     NOT NULL,
    ownership                          VARCHAR(7)     NOT NULL,
    gender_type                        VARCHAR(5)     NOT NULL,
    boarding_status                    VARCHAR(13)    NOT NULL,
    free_shs_category                  VARCHAR(14)    NOT NULL,
    has_electricity                    BOOLEAN        NOT NULL,
    has_potable_water                  BOOLEAN        NOT NULL,
    has_girls_toilets                  BOOLEAN        NOT NULL,
    has_ict_lab                        BOOLEAN        NOT NULL,
    has_library                        BOOLEAN        NOT NULL,
    num_classrooms                     SMALLINT       NOT NULL,
    distance_to_district_capital_km    DECIMAL(5,1)   NOT NULL,
    effective_from                     DATE           NOT NULL,
    effective_to                       DATE           NOT NULL,
    is_current                         BOOLEAN        NOT NULL,
    version_no                         SMALLINT       NOT NULL,
    CONSTRAINT uq_dim_school_version UNIQUE (emis_code, version_no),
    CONSTRAINT ck_dim_school_dates CHECK (effective_from <= effective_to)
);

-- dim_learner: One row per examination candidate (pseudonymised). SCD: Type 1
CREATE TABLE dim_learner (
    learner_key                        INTEGER        PRIMARY KEY,
    learner_pseudo_id                  VARCHAR(12)    NOT NULL,
    sex                                VARCHAR(6)     NOT NULL,
    learner_level                      VARCHAR(3)     NOT NULL,
    age_at_entry                       SMALLINT       NOT NULL,
    disability_type                    VARCHAR(12)    NOT NULL,
    home_language                      VARCHAR(8)     NOT NULL,
    guardian_occupation                VARCHAR(14)    NOT NULL,
    distance_home_to_school_km         DECIMAL(4,1)   NOT NULL,
    free_shs_beneficiary               VARCHAR(14)    NOT NULL,
    lives_with                         VARCHAR(8)     NOT NULL,
    shs_programme                      VARCHAR(20)    NOT NULL
);

-- dim_subject: One row per examination subject per examination level. SCD: Type 1
CREATE TABLE dim_subject (
    subject_key                        INTEGER        PRIMARY KEY,
    subject_code                       VARCHAR(8)     NOT NULL,
    subject_name                       VARCHAR(30)    NOT NULL,
    exam_level                         VARCHAR(6)     NOT NULL,
    core_or_elective                   VARCHAR(8)     NOT NULL,
    stem_flag                          BOOLEAN        NOT NULL
);

-- dim_examination: One row per examination type per year per sitting. SCD: Type 1
CREATE TABLE dim_examination (
    exam_key                           INTEGER        PRIMARY KEY,
    exam_type                          VARCHAR(8)     NOT NULL,
    exam_year                          SMALLINT       NOT NULL,
    sitting                            VARCHAR(8)     NOT NULL,
    examining_body                     VARCHAR(6)     NOT NULL,
    candidate_class                    VARCHAR(4)     NOT NULL,
    first_paper_date                   DATE           NOT NULL
);

-- dim_teacher: One row per subject teacher in an examination-sitting school (current snapshot). SCD: Type 1
CREATE TABLE dim_teacher (
    teacher_key                        INTEGER        PRIMARY KEY,
    staff_pseudo_id                    VARCHAR(10)    NOT NULL,
    sex                                VARCHAR(6)     NOT NULL,
    highest_qualification              VARCHAR(40)    NOT NULL,
    is_trained                         BOOLEAN        NOT NULL,
    ges_rank                           VARCHAR(30)    NOT NULL,
    subject_specialism                 VARCHAR(30)    NOT NULL,
    years_of_service                   SMALLINT       NOT NULL,
    teaches_in_home_district           BOOLEAN        NOT NULL,
    employment_type                    VARCHAR(20)    NOT NULL
);

-- dim_academic_term: One row per academic term. SCD: Type 0 (static)
CREATE TABLE dim_academic_term (
    term_key                           INTEGER        PRIMARY KEY,
    academic_year                      VARCHAR(9)     NOT NULL,
    term_number                        SMALLINT       NOT NULL,
    term_label                         VARCHAR(20)    NOT NULL,
    term_start_date                    DATE           NOT NULL,
    term_end_date                      DATE           NOT NULL
);

-- fact_exam_result: One row per candidate per subject per examination. SCD: n/a
CREATE TABLE fact_exam_result (
    exam_result_id                     BIGINT         PRIMARY KEY,
    learner_key                        INTEGER        NOT NULL,
    school_key                         INTEGER        NOT NULL,
    location_key                       INTEGER        NOT NULL,
    subject_key                        INTEGER        NOT NULL,
    exam_key                           INTEGER        NOT NULL,
    exam_date_key                      INTEGER        NOT NULL,
    teacher_key                        INTEGER        NOT NULL,
    candidate_index_no                 VARCHAR(24)    NOT NULL,
    raw_score                          DECIMAL(4,1),
    grade                              VARCHAR(3)     NOT NULL,
    grade_point                        SMALLINT,
    is_passed                          BOOLEAN        NOT NULL,
    is_absent                          BOOLEAN        NOT NULL,
    CONSTRAINT fk_fact_exam_result_learner_key FOREIGN KEY (learner_key) REFERENCES dim_learner (learner_key),
    CONSTRAINT fk_fact_exam_result_school_key FOREIGN KEY (school_key) REFERENCES dim_school (school_key),
    CONSTRAINT fk_fact_exam_result_location_key FOREIGN KEY (location_key) REFERENCES dim_location (location_key),
    CONSTRAINT fk_fact_exam_result_subject_key FOREIGN KEY (subject_key) REFERENCES dim_subject (subject_key),
    CONSTRAINT fk_fact_exam_result_exam_key FOREIGN KEY (exam_key) REFERENCES dim_examination (exam_key),
    CONSTRAINT fk_fact_exam_result_exam_date_key FOREIGN KEY (exam_date_key) REFERENCES dim_date (date_key),
    CONSTRAINT fk_fact_exam_result_teacher_key FOREIGN KEY (teacher_key) REFERENCES dim_teacher (teacher_key),
    CONSTRAINT ck_absent_score CHECK ((is_absent AND raw_score IS NULL) OR (NOT is_absent AND raw_score IS NOT NULL))
);

-- fact_enrolment: One row per school per class per academic term. SCD: n/a
CREATE TABLE fact_enrolment (
    enrolment_id                       BIGINT         PRIMARY KEY,
    school_key                         INTEGER        NOT NULL,
    location_key                       INTEGER        NOT NULL,
    term_key                           INTEGER        NOT NULL,
    snapshot_date_key                  INTEGER        NOT NULL,
    class_name                         VARCHAR(4)     NOT NULL,
    enrolled_boys                      INTEGER        NOT NULL,
    enrolled_girls                     INTEGER        NOT NULL,
    pupils_with_disability             INTEGER        NOT NULL,
    avg_daily_attendance               DECIMAL(6,1)   NOT NULL,
    dropouts_boys                      INTEGER        NOT NULL,
    dropouts_girls                     INTEGER        NOT NULL,
    repeaters                          INTEGER        NOT NULL,
    transfers_in                       INTEGER        NOT NULL,
    transfers_out                      INTEGER        NOT NULL,
    CONSTRAINT fk_fact_enrolment_school_key FOREIGN KEY (school_key) REFERENCES dim_school (school_key),
    CONSTRAINT fk_fact_enrolment_location_key FOREIGN KEY (location_key) REFERENCES dim_location (location_key),
    CONSTRAINT fk_fact_enrolment_term_key FOREIGN KEY (term_key) REFERENCES dim_academic_term (term_key),
    CONSTRAINT fk_fact_enrolment_snapshot_date_key FOREIGN KEY (snapshot_date_key) REFERENCES dim_date (date_key)
);

-- fact_staffing: One row per school per academic term. SCD: n/a
CREATE TABLE fact_staffing (
    staffing_id                        BIGINT         PRIMARY KEY,
    school_key                         INTEGER        NOT NULL,
    location_key                       INTEGER        NOT NULL,
    term_key                           INTEGER        NOT NULL,
    snapshot_date_key                  INTEGER        NOT NULL,
    trained_teachers                   SMALLINT       NOT NULL,
    untrained_teachers                 SMALLINT       NOT NULL,
    female_teachers                    SMALLINT       NOT NULL,
    teacher_vacancies                  SMALLINT       NOT NULL,
    total_enrolment                    INTEGER        NOT NULL,
    pupil_teacher_ratio                DECIMAL(5,1)   NOT NULL,
    pupil_trained_teacher_ratio        DECIMAL(5,1)   NOT NULL,
    CONSTRAINT fk_fact_staffing_school_key FOREIGN KEY (school_key) REFERENCES dim_school (school_key),
    CONSTRAINT fk_fact_staffing_location_key FOREIGN KEY (location_key) REFERENCES dim_location (location_key),
    CONSTRAINT fk_fact_staffing_term_key FOREIGN KEY (term_key) REFERENCES dim_academic_term (term_key),
    CONSTRAINT fk_fact_staffing_snapshot_date_key FOREIGN KEY (snapshot_date_key) REFERENCES dim_date (date_key)
);

-- Helpful indexes on fact foreign keys
CREATE INDEX ix_fact_exam_result_learner_key ON fact_exam_result (learner_key);
CREATE INDEX ix_fact_exam_result_school_key ON fact_exam_result (school_key);
CREATE INDEX ix_fact_exam_result_location_key ON fact_exam_result (location_key);
