CREATE INDEX ix_fact_exam_result_exam_key ON fact_exam_result (exam_key);
CREATE INDEX ix_fact_exam_result_exam_date_key ON fact_exam_result (exam_date_key);
CREATE INDEX ix_fact_exam_result_teacher_key ON fact_exam_result (teacher_key);
CREATE INDEX ix_fact_enrolment_school_key ON fact_enrolment (school_key);
CREATE INDEX ix_fact_enrolment_location_key ON fact_enrolment (location_key);
CREATE INDEX ix_fact_enrolment_term_key ON fact_enrolment (term_key);
CREATE INDEX ix_fact_enrolment_snapshot_date_key ON fact_enrolment (snapshot_date_key);
CREATE INDEX ix_fact_staffing_school_key ON fact_staffing (school_key);
CREATE INDEX ix_fact_staffing_location_key ON fact_staffing (location_key);
CREATE INDEX ix_fact_staffing_term_key ON fact_staffing (term_key);
CREATE INDEX ix_fact_staffing_snapshot_date_key ON fact_staffing (snapshot_date_key);
